rom storage.migrations s union all select 'storage.objects' name,count(*)::int count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) fingerprint from storage.objects s union all select 'storage.s3_multipart_uploads' name,count(*)::int count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) fingerprint from storage.s3_multipart_uploads s union all select 'storage.s3_multipart_uploads_parts' name,count(*)::int count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) fingerprint from storage.s3_multipart_uploads_parts s union all select 'storage.vector_indexes' name,count(*)::int count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) fingerprint from storage.vector_indexes s union all select 'vault.secrets' name,count(*)::int count,md5(coalesce(string_agg(md5(to_jsonb(s)::text),'' order by md5(to_jsonb(s)::text)),'')) fingerprint from vault.secrets s)x) then raise exception 'Retained data changed';end if;
